<script setup lang="ts">
import { ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useSimulationStore } from '@/stores/simulation'
import RobotViewport from '@/components/RobotViewport.vue'
import RobotControl from '@/components/RobotControl.vue'
import TelemetryChart from '@/components/TelemetryChart.vue'
import AppIcon from '@/components/AppIcon.vue'
import AppDialog from '@/components/AppDialog.vue'
const sim = useSimulationStore()
const route = useRoute()
watch(() => route.meta.robot, robot => { if (robot === 'quadruped' || robot === 'humanoid') sim.select(robot) }, { immediate: true })
const resetDialog = ref(false)
function reset() { sim.send({ type: 'reset' }, '仿真会话已重置（已有急停锁定保留）'); resetDialog.value = false }
</script>
<template>
  <div class="workbench">
    <div class="page-heading"><div><div class="workspace-eyebrow">NEXT ROBOTICS / {{ route.meta.section }}</div><h1>{{ route.meta.title }}<span class="heading-dot">.</span></h1><p>控制协调步态、灵巧手与独立关节，探索末端 IK 和动作回放。</p></div><div class="page-actions"><button class="btn btn-ghost" @click="resetDialog = true"><AppIcon name="reset" />重置场景</button><button class="btn" :class="{ 'btn-primary': sim.snapshot.paused }" @click="sim.send({ type: 'pause', value: !sim.snapshot.paused }, sim.snapshot.paused ? '已继续仿真' : '已暂停全部仿真')"><AppIcon :name="sim.snapshot.paused ? 'play' : 'pause'" />{{ sim.snapshot.paused ? '继续仿真' : '暂停仿真' }}</button></div></div>
    <div v-if="sim.error" class="error-banner" role="alert"><AppIcon name="help" />{{ sim.error }}<button aria-label="关闭错误提示" @click="sim.error = ''"><AppIcon name="close" /></button></div>
    <div class="workbench-main"><RobotViewport /><RobotControl /></div>
    <section class="telemetry-overview panel"><div class="telemetry-heading"><div><h2>实时遥测</h2><span class="stream-label"><span class="dot" />{{ sim.snapshot.paused ? '采样已暂停' : '实时数据流' }}</span><small class="mono">{{ sim.definition.serial }}</small></div><RouterLink to="/telemetry">数据详情<AppIcon name="arrow" /></RouterLink></div><div class="telemetry-grid">
      <div class="telemetry-cell"><div class="metric-label"><AppIcon name="activity" /><span>步态速度</span><span class="metric-note">VELOCITY</span></div><div class="metric-number mono">{{ sim.current.speed.toFixed(2) }}<small>m/s</small><span class="metric-secondary">目标 {{ sim.current.targetSpeed.toFixed(1) }}</span></div><TelemetryChart :samples="sim.history" metric="speed" color="#bcf476" /></div>
      <div class="telemetry-cell"><div class="metric-label"><AppIcon name="temperature" /><span>电机温度</span><span class="metric-note">THERMAL</span></div><div class="metric-number mono">{{ sim.current.temperature.toFixed(1) }}<small>°C</small><span class="metric-secondary normal">{{ sim.current.temperature >= 60 ? '温度偏高' : '正常范围' }}</span></div><TelemetryChart :samples="sim.history" metric="temperature" color="#d7ba8a" /></div>
      <div class="telemetry-cell"><div class="metric-label"><AppIcon name="bolt" /><span>系统功率</span><span class="metric-note">POWER</span></div><div class="metric-number mono">{{ sim.current.power.toFixed(1) }}<small>W</small><span class="metric-secondary">驱动与控制</span></div><TelemetryChart :samples="sim.history" metric="power" color="#85bbc8" /></div>
      <div class="telemetry-cell battery-cell"><div class="metric-label"><AppIcon name="battery" /><span>电池状态</span><span class="metric-note">BATTERY</span></div><div class="metric-number mono">{{ sim.current.battery.toFixed(1) }}<small>%</small></div><div class="battery-bars" role="meter" aria-label="模拟电池电量" :aria-valuenow="sim.current.battery" aria-valuemin="0" aria-valuemax="100"><span v-for="n in 24" :key="n" :class="{ filled: n / 24 <= sim.current.battery / 100 }" /></div><div class="battery-caption"><span><i class="dot" /> {{ sim.current.battery > 20 ? '电量充足' : '电量较低' }}</span><span>{{ sim.snapshot.paused ? '采样已冻结' : sim.current.emergency ? '输出关闭' : '模拟放电中' }}</span></div></div>
    </div></section>
    <div class="workspace-footnote"><span><AppIcon name="shield" />当前为运动学仿真环境，数据不代表真实设备性能。</span><span class="mono">SIM ENGINE / 10 Hz <span class="dot" /></span></div>
    <AppDialog :open="resetDialog" title="重置仿真会话" @close="resetDialog = false"><p class="reset-explanation">两台机器人将恢复初始站姿、朝向与电量，清空遥测曲线并重新计时。运行日志和急停锁定会保留。</p><div class="dialog-actions"><button class="btn btn-ghost" @click="resetDialog = false">取消</button><button class="btn btn-primary" @click="reset">确认重置</button></div></AppDialog>
  </div>
</template>
